  SET "created_at" = COALESCE(NEW."created_at", CAST((julianday('now') - 2440587.5) * 86400000 AS INTEGER)), "updated_at" = COALESCE(NEW."updated_at", CAST((julianday('now') - 2440587.5) * 86400000 AS INTEGER))
  WHERE "id" = NEW."id";
END;
DROP TRIGGER IF EXISTS "trg_fuel_refills_timestamps_update";
CREATE TRIGGER "trg_fuel_refills_timestamps_update"
AFTER UPDATE ON "fuel_refills"
FOR EACH ROW
WHEN NEW."updated_at" IS OLD."updated_at"
BEGIN
  UPDATE "fuel_refills"
  SET "updated_at" = CAST((julianday('now') - 2440587.5) * 86400000 AS INTEGER)
  WHERE "id" = NEW."id";
END;

-- TripLogs -> trip_logs
CREATE TABLE IF NOT EXISTS "trip_logs" ("id" INTEGER PRIMARY KEY AUTOINCREMENT, "date" INTEGER DEFAULT NULL, "distance_traveled" REAL NOT NULL, "average_consumption" REAL, "is_counter_reset" INTEGER, "trip_type" TEXT, "notes" TEXT, "created_at" INTEGER DEFAULT NULL, "updated_at" INTEGER DEFAULT NULL, "deleted_at" INTEGER DEFAULT NULL);
CREATE INDEX IF NOT EXISTS "idx_trip_logs_active" ON "trip_logs" ("date") WHERE deleted_at IS NULL;
DROP TRIGGER IF EXISTS "trg_trip_logs_timestamps_insert";
CREATE TRIGGER "trg_trip_logs_timestamps_insert"
AFTER INSERT ON "trip_logs"
FOR EACH ROW
WHEN NEW."created_at" IS NULL OR NEW."updated_at" IS NULL
BEGIN
  UPDATE "trip_logs"
  SET "created_at" = COALESCE(NEW."created_at", CAST((julianday('now') - 2440587.5) * 86400000 AS INTEGER)), "updated_at" = COALESCE(NEW."updated_at", CAST((julianday('now') - 2440587.5) * 86400000 AS INTEGER))
  WHERE "id" = NEW."id";
END;
DROP TRIGGER IF EXISTS "trg_trip_logs_timestamps_update";
CREATE TRIGGER "trg_trip_logs_timestamps_update"
AFTER UPDATE ON "trip_logs"
FOR EACH ROW
WHEN NEW."updated_at" IS OLD."updated_at"
BEGIN
  UPDATE "trip_logs"
  SET "updated_at" = CAST((julianday('now') - 2440587.5) * 86400000 AS INTEGER)
  WHERE "id" = NEW."id";
END;

